import {find,isLocked,selectionRoots,locate} from '../document/model.js';import {escape} from '../renderer/svg.js';import {shapeTools} from './shapes-menu.js';import {editorAction,editorInput} from './editor.js';import {showHelp} from './help.js';
const button=(action,label,disabled=false)=>`<button data-edit="${action}" ${disabled?'disabled':''}>${label}</button>`;
export function renderContext(a){const el=document.querySelector('#context-bar'),n=find(a.doc,a.selected[0]),disabled=!n||isLocked(a.doc,n.id);let mode=a.tool==='mesh'?'Mesh shading':a.tool==='direct'?'Edit points':shapeTools.includes(a.tool)?'Drawing: '+({rect:'Rectangle',ellipse:'Ellipse',triangle:'Triangle',polygon:'Polygon',star:'Star',line:'Line'}[a.tool]):a.tool==='select'?'Select objects':a.tool==='path'?'Draw a path':a.tool==='pencil'?'Draw with Pencil':a.tool==='text'?'Add text':'Pan canvas',body='';
 if(a.selected.length>1){mode=a.selected.length+' selected';const roots=selectionRoots(a.doc,a.selected),same=roots.length>1&&roots.every(n=>!isLocked(a.doc,n.id)&&locate(a.doc,n.id).list===locate(a.doc,roots[0].id).list),canCombine=same&&roots.every(n=>['rectangle','ellipse'].includes(n.type)||['path','freehand'].includes(n.type)&&(n.closed||n.rawPath||n.nodes.some(p=>p.close))),canJoin=same&&roots.length===2&&roots.every(n=>['path','freehand'].includes(n.type)&&!n.rawPath&&n.nodes.length>=2&&!n.closed&&!n.nodes.some(p=>p.close));body=`<span class="context-label">Combine shapes</span>${button('combine-union','Unite',!canCombine)}${button('combine-subtract','Subtract front',!canCombine)}${button('combine-intersect','Keep overlap',!canCombine)}${button('combine-exclude','Exclude overlap',!canCombine)}${button('combine-compound','Compound path',!canCombine)}${button('join','Join paths',!canJoin)}<span class="context-note">${canCombine?'Combining uses the current frame. Undo restores the originals.':'Choose closed shapes in the same group to combine.'}</span>`;}
 else if(n&&a.tool==='mesh'&&n.mesh){const index=Math.min(a.activeMesh||0,n.mesh.points.length-1),p=n.mesh.points[index];mode=`Mesh · ${n.name} · point ${index+1}`;body=`<label class="context-color">Point colour<input type="color" aria-label="Selected mesh point colour" data-mesh-prop="color" value="${p.color}" ${disabled?'disabled':''}></label>${button('mesh-split','Subdivide cell',disabled||n.mesh.rows>=7||n.mesh.cols>=7)}<button data-edit="mesh-tap" aria-pressed="${!!a.meshSplit}" ${n.mesh.rows>=7||n.mesh.cols>=7?'disabled':''} class="${a.meshSplit?'active':''}" ${disabled?'disabled':''}>Tap to subdivide</button>${button('mesh-row','More rows',disabled||n.mesh.rows>=7)}${button('mesh-col','More columns',disabled||n.mesh.cols>=7)}<span class="context-note">${n.mesh.rows} × ${n.mesh.cols} grid · hold a point for colour · maximum 7 × 7</span>`;}
 else if(n&&a.nodeEdit&&['path','freehand'].includes(n.type)&&!n.rawPath){mode=`Edit points · ${n.name}${Number.isInteger(a.activeNode)?' · point '+(a.activeNode+1):''}`;const pointDisabled=disabled||!Number.isInteger(a.activeNode);body=button('previous-point','‹ Point',disabled)+button('next-point','Point ›',disabled)+button('split','Add midpoint',pointDisabled)+button('smooth','Smooth point',pointDisabled)+button('corner','Corner point',pointDisabled)+button('delete-point','Delete point',pointDisabled)+button('toggle-close',n.closed||n.nodes.some(p=>p.close)?'Open path':'Close path',disabled)+button('reverse','Reverse path',disabled)+button('shape-key','◇ Keyframe shape',disabled);}
 else if(n){if(n.type==='text')mode='Edit text';mode+=' · '+n.name;body=button('direct',n.type==='text'?'Edit text':n.type==='group'?'Direct select':'Edit points',disabled)+(n.type==='group'?button('contents','Select contents',disabled):n.type!=='text'?button('mesh','Mesh shading',disabled):'')+`<button data-add-key ${disabled?'disabled':''}>◇ Add keyframe</button>`;}
 else body='<span class="context-note">Choose Shapes → draw → Add keyframe. Drag empty canvas to select several.</span>';
 const active=document.activeElement;if(el.contains(active)&&active.matches('[data-mesh-prop]'))return;el.innerHTML=`<div class="context-heading"><strong>${escape(mode)}</strong><div class="context-header-actions"><button data-context-help>How to animate</button><button class="context-properties" data-properties>Properties</button></div></div><div class="context-actions">${body}</div>`;
}
export function bindContext(a){const el=document.querySelector('#context-bar');el.addEventListener('click',e=>{const action=e.target.closest('[data-edit]')?.dataset.edit;if(action)return a.safe(()=>editorAction(a,action));if(e.target.closest('[data-add-key]'))document.querySelector('#add-key').click();if(e.target.closest('[data-context-help]'))showHelp(a);if(e.target.closest('[data-properties]'))document.querySelector('.inspector').classList.add('open');});el.addEventListener('input',e=>editorInput(a.properties,e));el.addEventListener('change',()=>{a.properties.flush();a.render();});}
